class HtmlTemplateCard extends HTMLElement {
    static get properties() {
        return {
            _config: {},
            _hass: {},
        };
    }

    set hass(hass) {
        const oldHass = this._hass;
        this._hass = hass;
        if (this._config && this._hass && !this._entities) {
            this.calculateEntites();
        }
        if (this.shouldUpdate(oldHass)) {
            this.processAndRender();
        }
    }

    shouldUpdate(oldHass) {
        if (oldHass && this._entities && !this._config.always_update) {
            let should = false;
            this._entities.forEach(entity => {
                should = should || oldHass.states[entity] !== this._hass.states[entity]
                    || oldHass.states[entity].attributes !== this._hass.states[entity].attributes
            });
            return should;
        }
        return true;
    }

    setConfig(config) {
        if (!config.content) {
            throw new Error("You need to define 'content' in your configuration.")
        }
        this._config = config;
        if (this._config && this._hass && !this._entities) {
            this.calculateEntites();
        }
        if (!this._config.picture_elements_mode) {
            let haCard = document.createElement("ha-card");
            haCard.style.padding = "16px";
            this._rootElement = haCard;
        } else {
            this._rootElement = document.createElement("div");
        }
    }

    calculateEntites() {
        this._entities = [];
        if (this._config.entities && Array.isArray(this._config.entities)) {
            for (const entity in this._config.entities) {
                this._entities.push(this._config.entities[entity]);
            }
        }
        for (const entity in this._hass.states) {
            if (this._config.content.includes(entity)) {
                this._entities.push(this._hass.states[entity].entity_id);
            }
        }
    }

    processAndRender() {
        let content = this._config.content;
        if (!this._config.ignore_line_breaks) {
            content = content.replace(/\r?\n|\r/g, "</br>");
        }
        if (!this._config.do_not_parse) {
            this._hass.connection.subscribeMessage(
                (msg) => this.render(msg.result),
                {type: "render_template", template: content}
            );
        } else {
            this.render(content);
        }
        if (!(this._rootElement in this.children)) {
            this.appendChild(this._rootElement);
        }
    }

    render(content) {
        let header = ``;
        if (this._config.title) {
            header = `<div class="card-header" style="padding: 8px 0 16px 0;"><div class="name">${this._config.title}</div></div>`;
        }
        this._rootElement.innerHTML = this._config.picture_elements_mode
            ? content
            : `${header}<div>${content}</div>`;
    }

    getCardSize() {
        return 1;
    }
    
    static getStubConfig () {
        return {
            title: "HTML with Templates",
            content: "Sun status: <b>{{ states('sun.sun') }}</b>\n\n<small>Generated by <i>HTML Jinja2 Card</i>!</small>",
            entities: [ "sun.sun" ]
        };
    }
    
    static getConfigElement () {
        return document.createElement("html-template-card-editor");
    }
    
}


class HtmlTemplateCardEditor extends HTMLElement {
    
    _hass;
    set hass(hass) {
        this._hass = hass;
        this._render();
    }
    
    _config = {};
    _configEntities = [];
    
    _rendered = false;
    
    constructor () {
        super();
    }
    
    setConfig (config) {
        this._config = config;
        this._configEntities = (this._config.entities || []).map(x => ({ entity: x }));
        this._render();
    }
    
    _updateConfig(newConfig) {
        this._config = { ...this._config, ...newConfig };
        this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: this._config } }));
    }
    
    _updateConfigEntities(newConfigEntities) {
        this._configEntities = newConfigEntities;
        const newEntities = this._configEntities.map(x => x.entity);
        this._config = { ...this._config, entities: newEntities };
        this._updateConfig();
    }
    
    SCHEMA = [
        {
            name: "title",
            selector: { text: {} }
        },
        {
            name: "content",
            required: true,
            selector: { template: {} }
        },
        {
            type: "grid",
            name: "",
            schema: [
                {
                    name: "picture_elements_mode",
                    selector: { boolean: {} },
                },
                {
                    name: "ignore_line_breaks",
                    selector: { boolean: {} },
                },
                {
                    name: "do_not_parse",
                    selector: { boolean: {} },
                },
                {
                    name: "always_update",
                    selector: { boolean: {} },
                },
            ]
        }
    ]
    
    async _render () {
        
        if (this._rendered) { return; }
        if (!this._hass || !this._config) {
            // console.error("[TEMPLATE_HTML] No hass or config!!!");
            return;
        }
        
        // load the needed <hui-entity-editor/> element
        (await customElements.get('hui-glance-card').getConfigElement()).requestUpdate();
        
        // console.log("[TEMPLATE_HTML] Rendering editor with config:", this._config);
        // console.log("[TEMPLATE_HTML] Current config entities:", this._configEntities);
        
        this.replaceChildren();
        
        const haForm = document.createElement("ha-form");
        haForm.hass = this._hass;
        haForm.data = this._config;
        haForm.schema = this.SCHEMA;
        haForm.computeLabel = this._computeLabel.bind(this);
        haForm.computeHelper = this._computeHelper.bind(this);
        haForm.addEventListener("value-changed", (e) => {
            this._updateConfig(e.detail.value);
        })
        this.appendChild(haForm);
        
        const haEntitiesForm = document.createElement("hui-entity-editor");
        haEntitiesForm.hass = this._hass;
        haEntitiesForm.entities = this._configEntities;
        // default is "Entities (required)"
        // by customize label, it can be "Entities" without "(required)" suffix
        haEntitiesForm.label = this._computeEntitiesLabel();
        haEntitiesForm.addEventListener("entities-changed", (e) => {
            this._updateConfigEntities(e.detail.entities);
            this._rendered = false;
            this._render();
        })
        this.appendChild(haEntitiesForm);
        
        this._rendered = true;
        
    }
    
    _computeLabel (schema) {
        switch (schema.name) {
            case "ignore_line_breaks":
                return "Ignore Line Breaks";
            case "do_not_parse":
                return "Do Not Parse Template";
            case "always_update":
                return "Always Update";
            case "picture_elements_mode":
                return "Picture Elements Mode";
            default:
        }
        return this._hass.localize(`ui.panel.lovelace.editor.card.generic.${schema.name}`) || schema.name;
    }
    
    _computeEntitiesLabel () {
        return this._hass.localize(`ui.panel.lovelace.editor.card.generic.entities`)
    }
    
    _computeHelper (schema) {
        switch (schema.name) {
            case "ignore_line_breaks":
                return "Disables changing line breaks to </br> tags";
            case "do_not_parse":
                return "Disables template parsing";
            case "always_update":
                return "Enables refreshing the card with every change of entity";
            case "picture_elements_mode":
                return "Enables picture-elements mode";
        }
        return undefined;
    }
    
}

customElements.define('html-template-card', HtmlTemplateCard);
customElements.define("html-template-card-editor", HtmlTemplateCardEditor);